set-variable.value:
@{
        var mode = (string)context.Variables["bing-guard-mode"];
        if (mode != "monitor" && mode != "enforce")
        {
            return "config:error";
        }
        var keywords = "{{bing-guard-allowed-keywords}}".ToLowerInvariant().Split(',');
        var domains = "{{bing-guard-allowed-domains}}".ToLowerInvariant().Split(',');
        var configured = false;
        for (var i = 0; i < keywords.Length; i++)
        {
            keywords[i] = keywords[i].Trim();
            if (keywords[i].Length == 0) { continue; }
            if (!System.Text.RegularExpressions.Regex.IsMatch(keywords[i], @"^[a-z0-9-]+$"))
            {
                return "config:error";
            }
            configured = true;
        }
        for (var i = 0; i < domains.Length; i++)
        {
            domains[i] = domains[i].Trim().TrimEnd('.');
            if (domains[i].Length == 0) { continue; }
            if (!System.Text.RegularExpressions.Regex.IsMatch(domains[i], @"^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$"))
            {
                return "config:error";
            }
            configured = true;
        }
        if (!configured) { return "config:error"; }
        var sorryUrl = "{{bing-guard-sorry-url}}";
        System.Uri sorryUri;
        /* A null base avoids UriKind, which APIM expressions do not expose. */
        if (System.Text.RegularExpressions.Regex.IsMatch(sorryUrl, @"[\x00-\x20\x7f\\]")
            || !System.Uri.TryCreate(null, sorryUrl, out sorryUri)
            || !sorryUri.IsAbsoluteUri
            || (sorryUri.Scheme != "https" && sorryUri.Scheme != "http")
            || !sorryUri.IsWellFormedOriginalString() || !string.IsNullOrEmpty(sorryUri.UserInfo))
        {
            return "config:error";
        }
        if (context.Response.StatusCode != 200) { return "skip:http-status"; }
        var mediaType = context.Response.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim();
        if (!mediaType.Equals("application/json", System.StringComparison.OrdinalIgnoreCase))
        {
            return "skip:content-type";
        }
        Newtonsoft.Json.Linq.JObject payload;
        try
        {
            payload = context.Response.Body.As<Newtonsoft.Json.Linq.JToken>(preserveContent: true) as Newtonsoft.Json.Linq.JObject;
        }
        catch (System.Exception exception)
        {
            if (exception.Source == "Newtonsoft.Json")
            {
                return "skip:invalid-json";
            }
            throw;
        }
        if (payload == null) { return "skip:unexpected-shape"; }
        var pages = payload["webPages"] as Newtonsoft.Json.Linq.JObject;
        if (pages == null) { return "skip:no-webpages"; }
        var results = pages["value"] as Newtonsoft.Json.Linq.JArray;
        if (results == null) { return "skip:unexpected-shape"; }
        if (results.Count == 0) { return "skip:empty"; }
        var urls = new System.Collections.Generic.List<string>();
        foreach (var item in results)
        {
            var result = item as Newtonsoft.Json.Linq.JObject;
            urls.Add(result != null && result["url"] != null && result["url"].Type == Newtonsoft.Json.Linq.JTokenType.String
                ? (string)result["url"] : "");
            if (result == null || result["deepLinks"] == null) { continue; }
            var links = result["deepLinks"] as Newtonsoft.Json.Linq.JArray;
            if (links == null) { urls.Add(""); continue; }
            foreach (var link in links)
            {
                var deepLink = link as Newtonsoft.Json.Linq.JObject;
                urls.Add(deepLink != null && deepLink["url"] != null && deepLink["url"].Type == Newtonsoft.Json.Linq.JTokenType.String
                    ? (string)deepLink["url"] : "");
            }
        }
        var violations = new System.Collections.Generic.List<string>();
        foreach (var rawUrl in urls)
        {
            var host = "[invalid-url]";
            var allowed = false;
            System.Uri uri;
            if (!string.IsNullOrWhiteSpace(rawUrl)
                && !System.Text.RegularExpressions.Regex.IsMatch(rawUrl, @"[\x00-\x20\x7f\\]")
                && System.Uri.TryCreate(null, rawUrl, out uri)
                && uri.IsAbsoluteUri
                && (uri.Scheme == "https" || uri.Scheme == "http")
                && uri.IsWellFormedOriginalString() && string.IsNullOrEmpty(uri.UserInfo))
            {
                host = uri.IdnHost.TrimEnd('.').ToLowerInvariant();
                foreach (var keyword in keywords)
                {
                    if (keyword.Length > 0 && host.Contains(keyword)) { allowed = true; break; }
                }
                foreach (var domain in domains)
                {
                    if (domain.Length > 0 && (host == domain || host.EndsWith("." + domain, System.StringComparison.Ordinal)))
                    {
                        allowed = true;
                        break;
                    }
                }
            }
            if (!allowed && !violations.Contains(host) && violations.Count < 10) { violations.Add(host); }
        }
        return string.Join(",", violations);
      }

metadata.value:
@{
              var query = context.Request.Url.Query.GetValueOrDefault("q", "");
              if (string.IsNullOrWhiteSpace(System.Uri.UnescapeDataString(query.Replace("+", " ")))) { return "unspecified"; }
              return query.Length > 100 ? query.Substring(0, 100) : query;
            }

otherwise.set-body:
@{
                var original = context.Response.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
                var title = "{{bing-guard-sorry-title}}";
                var snippet = "{{bing-guard-sorry-snippet}}";
                var url = "{{bing-guard-sorry-url}}";
                var id = "https://api.bing.microsoft.com/api/v7/#WebPages.0";
                var result = new Newtonsoft.Json.Linq.JObject(
                    new Newtonsoft.Json.Linq.JProperty("id", id),
                    new Newtonsoft.Json.Linq.JProperty("name", title),
                    new Newtonsoft.Json.Linq.JProperty("url", url),
                    new Newtonsoft.Json.Linq.JProperty("displayUrl", url),
                    new Newtonsoft.Json.Linq.JProperty("snippet", snippet),
                    new Newtonsoft.Json.Linq.JProperty("dateLastCrawled", System.DateTime.UtcNow.ToString("o")),
                    new Newtonsoft.Json.Linq.JProperty("language", "en"),
                    new Newtonsoft.Json.Linq.JProperty("isFamilyFriendly", true),
                    new Newtonsoft.Json.Linq.JProperty("isNavigational", false));
                var pages = new Newtonsoft.Json.Linq.JObject(
                    new Newtonsoft.Json.Linq.JProperty("totalEstimatedMatches", 1),
                    new Newtonsoft.Json.Linq.JProperty("value", new Newtonsoft.Json.Linq.JArray(result)));
                var originalPages = (Newtonsoft.Json.Linq.JObject)original["webPages"];
                if (originalPages["webSearchUrl"] != null) { pages["webSearchUrl"] = originalPages["webSearchUrl"].DeepClone(); }
                var replacement = new Newtonsoft.Json.Linq.JObject(
                    new Newtonsoft.Json.Linq.JProperty("_type", "SearchResponse"),
                    new Newtonsoft.Json.Linq.JProperty("webPages", pages));
                if (original["queryContext"] != null) { replacement["queryContext"] = original["queryContext"].DeepClone(); }
                if (original["rankingResponse"] != null)
                {
                    replacement["rankingResponse"] = new Newtonsoft.Json.Linq.JObject(
                        new Newtonsoft.Json.Linq.JProperty("mainline", new Newtonsoft.Json.Linq.JObject(
                            new Newtonsoft.Json.Linq.JProperty("items", new Newtonsoft.Json.Linq.JArray(
                                new Newtonsoft.Json.Linq.JObject(
                                    new Newtonsoft.Json.Linq.JProperty("answerType", "WebPages"),
                                    new Newtonsoft.Json.Linq.JProperty("resultIndex", 0),
                                    new Newtonsoft.Json.Linq.JProperty("value", new Newtonsoft.Json.Linq.JObject(
                                        new Newtonsoft.Json.Linq.JProperty("id", id)))))))));
                }
                return replacement.ToString(Newtonsoft.Json.Formatting.None);
              }
